from __future__ import annotations

import base64
import gzip
import hashlib
import json
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SOURCE = ROOT / "growth6-source" / "v6.1.html"
CSS_B64 = ""
JS_B64 = ""
BUILD = "2026.08.31-payroll-team-readability"
VERSION = "6.1.0"

CSS_START = "/* PAYROLL_TEAM_READABILITY_CSS_V1_START */"
CSS_END = "/* PAYROLL_TEAM_READABILITY_CSS_V1_END */"
JS_START = "// PAYROLL_TEAM_READABILITY_V1_START"
JS_END = "// PAYROLL_TEAM_READABILITY_V1_END"


def remove_marked_block(text: str, start: str, end: str) -> str:
    pattern = re.compile(r"\n?" + re.escape(start) + r".*?" + re.escape(end) + r"\n?", re.S)
    return pattern.sub("\n", text)


def main() -> None:
    html = SOURCE.read_text(encoding="utf-8")
    css = gzip.decompress(base64.b64decode(CSS_B64)).decode("utf-8").strip()
    js = gzip.decompress(base64.b64decode(JS_B64)).decode("utf-8").strip()

    html = remove_marked_block(html, CSS_START, CSS_END)
    html = remove_marked_block(html, JS_START, JS_END)

    html = re.sub(r"const BUILD='[^']+';", f"const BUILD='{BUILD}';", html, count=1)
    html = html.replace("Growth OS <span>6.0</span>", "Growth OS <span>6.1</span>")
    html = html.replace("GROWTH OS <span>6.0</span>", "GROWTH OS <span>6.1</span>")

    task_save_old = "priority:v.priority,status:v.status,createdBy:"
    task_save_new = "priority:v.priority,status:v.status,required:f.elements.required?.checked||false,createdBy:"
    if task_save_new not in html:
        if task_save_old not in html:
            raise RuntimeError("Task save insertion point was not found")
        html = html.replace(task_save_old, task_save_new, 1)

    style_index = html.find("</style>")
    if style_index < 0:
        raise RuntimeError("Main style closing tag was not found")
    html = html[:style_index] + "\n" + css + "\n" + html[style_index:]

    listener_marker = "document.addEventListener('click',handleClick);"
    js_index = html.find(listener_marker)
    if js_index < 0:
        raise RuntimeError("Application event-listener insertion point was not found")
    html = html[:js_index] + js + "\n\n" + html[js_index:]

    required_markers = [
        "const VERSION='6.1.0'",
        f"const BUILD='{BUILD}'",
        CSS_START,
        JS_START,
        "function renderPayroll()",
        "function adminMonthStats(adminId",
        "function mentorPayrollStats(mentorId",
        "ЗП и мотивация",
        "МОЯ ЗАРПЛАТА ЗА МЕСЯЦ",
        "Обязательная задача — влияет на бонус администратора",
        "required:f.elements.required?.checked||false",
        "settings.uiScale",
        "personalRoleLink",
    ]
    missing = [marker for marker in required_markers if marker not in html]
    if missing:
        raise RuntimeError(f"Missing release markers: {missing}")

    target_paths = [
        SOURCE,
        ROOT / "growth-os" / "index.html",
        ROOT / "growth61-live" / "index.html",
        ROOT / "growth-os-6" / "index.html",
    ]
    for target in target_paths:
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(html, encoding="utf-8")

    build_payload = {
        "version": VERSION,
        "build": BUILD,
        "features": [
            "administrator salary and motivation rules from uploaded workbook",
            "administrator salary forecast and shift calendar",
            "personal administrator cabinets",
            "owner-managed mentor payroll entries",
            "personal mentor cabinets with payroll breakdown",
            "dynamic mentor add, archive and restore",
            "personal staff access links",
            "readability scale 100, 110 and 120 percent",
            "mandatory tasks linked to administrator bonus",
        ],
    }
    release_text = "\n".join(
        [
            "EXTREME KIDS Growth OS 6.1.0",
            f"Build: {BUILD}",
            "Administrator salary automation: ready",
            "Administrator personal cabinets and salary forecast: ready",
            "Mentor payroll and personal cabinets: ready",
            "Dynamic mentor management: ready",
            "Comfort readability mode: ready",
            "Uploaded workbook motivation rules: integrated",
            "",
        ]
    )
    for folder in ("growth-os", "growth61-live", "growth-os-6"):
        out = ROOT / folder
        out.mkdir(parents=True, exist_ok=True)
        (out / "BUILD.json").write_text(json.dumps(build_payload, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
        (out / "RELEASE.txt").write_text(release_text, encoding="utf-8")

    digest = hashlib.sha256(html.encode("utf-8")).hexdigest()
    (ROOT / "growth6-source" / "SHA256.txt").write_text(digest + "\n", encoding="utf-8")
    print(json.dumps({"version": VERSION, "build": BUILD, "bytes": len(html.encode('utf-8')), "sha256": digest}, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()
